import numpy as np,pandas as pd,tifffile as tif
from pathlib import Path
from scipy import ndimage as ndi
from skimage.feature import peak_local_max
from skimage.segmentation import watershed
manual={p.stem:pd.read_csv(p,sep='\t') for p in Path('/task/input/annotations').glob('*.tsv')}
imgs={w:tif.imread(f'/task/input/images/{w}_ch1.tif').astype(float)-100 for w in manual}

def count(w,thr,minarea,mode,sigma,dist):
 im=imgs[w];cc,n=ndi.label(im>thr);areas=np.bincount(cc.ravel());areas[0]=0
 total=0; masks=np.zeros_like(cc,np.int32);nxt=1
 for cid in np.flatnonzero(areas>=minarea):
  sl=ndi.find_objects(cc==cid)[0];sub=cc[sl]==cid
  dt=ndi.distance_transform_edt(sub)
  if mode=='dist': sig=dt
  elif mode=='int': sig=ndi.gaussian_filter(im[sl],sigma) if sigma else im[sl]
  elif mode=='both': sig=ndi.gaussian_filter(im[sl],sigma) if sigma else im[sl]
  if mode=='both':
   # Intensity peaks only if plausibly separated in distance; combine candidate sets.
   ci=peak_local_max(sig,min_distance=dist,threshold_abs=350,exclude_border=False)
   cd=peak_local_max(dt,min_distance=dist,threshold_abs=.8,exclude_border=False)
   coords=list(map(tuple,ci)); coords2=list(map(tuple,cd))
   # Greedily combine, preferring intensity then distance, suppress close duplicates.
   coords=sorted(coords+coords2,key=lambda p:(sig[p[0],p[1]],dt[p[0],p[1]]),reverse=True)
   keep=[]
   for p in coords:
    if all((p[0]-q[0])**2+(p[1]-q[1])**2>=dist*dist for q in keep):keep.append(p)
   co=np.array(keep,np.int32)
  else:
   co=peak_local_max(sig,min_distance=dist,threshold_abs=.8 if mode=='dist' else 350,exclude_border=False)
  if len(co)==0:co=np.array([np.unravel_index(np.argmax(dt),dt.shape)])
  mk=np.zeros(sub.shape,np.int32)
  for j,(r,c) in enumerate(co):mk[r,c]=nxt+j
  # Watershed negative distance, but markers from intensity may lie outside threshold submask.
  wl=watershed(-dt,mk,mask=sub);tmp=masks[sl];tmp[sub]=wl[sub];masks[sl]=tmp;nxt+=len(co);total+=len(co)
 # edge exclusion
 bad=[]
 for cid in range(1,nxt):
  rr,cc=np.where(masks==cid)
  if len(rr) and (rr.max()>=319 or cc.max()>=319):bad.append(cid)
 for cid in bad:masks[masks==cid]=0
 return len(set(np.unique(masks))-{0}), total-len(bad)

for mode in ['dist','int','both']:
 for sigma in ([0,.5,1,1.5] if mode!='dist' else [0]):
  for dist in [2,3,4,5]:
   for minarea in [30,35,40,45]:
    vals=[];ptsrec=[]
    for w,d in sorted(manual.items()):
     n,_=count(w,350,minarea,mode,sigma,dist);m=len(d);vals.append((w,n,m,abs(n-m)<=max(3,.1*m)))
    if all(v[3] for v in vals):
     mae=np.mean([abs(v[1]-v[2]) for v in vals]);mx=max(abs(v[1]-v[2])/max(v[2],1) for v in vals)
     print(mode,'sig',sigma,'dist',dist,'area',minarea,'MAE',round(mae,3),'maxrel',round(mx,3),' '.join(f'{w}:{n}/{m}' for w,n,m,_ in vals),flush=True)
